{"file_path": "data/eval/workspace/E24_timeout.py", "content": "import subprocess
import sys

def run_with_timeout(command, timeout=2):
    """Run a command with a timeout. Print 'TIMEOUT' if it exceeds."""
    try:
        proc = subprocess.Popen(command, shell=True)
        proc.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        proc.kill()
        proc.wait()
        print('TIMEOUT')

if __name__ == '__main__':
    if len(sys.argv) > 1:
        run_with_timeout(sys.argv[1])
    else:
        print("Usage: python E24_timeout.py <command>")
"}

